mapper.select:
select 
  from FIN_OPEN_RULE
 where FIN_OPEN_RULE.CASH_ID = (select CASH_ID from FIN_CASH_INFO where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
								   and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
								   and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
								   and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}
								   )

select 
	from FIN_OPEN_PLAN
where FIN_OPEN_PLAN.CASH_ID = (select CASH_ID from FIN_CASH_INFO
								where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
								   and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
								   and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
								   and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType})
order by FIN_OPEN_PLAN.OPEN_VDATE,FIN_OPEN_PLAN.OPEN_DATE_STR
